#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string input_str;
    std::getline(std::cin, input_str);
    std::vector<char> chars;
    bool found_at = true;
    for (size_t position = 0; position < input_str.length(); ++position) {
        char current_char = input_str[position];
        if (position >= 2 && position < input_str.length() && 
            input_str.substr(position - 2, 3) == "dot" && 
            position != input_str.length() - 1 && position != 2) {
            if (!chars.empty()) {
                chars.pop_back();
            }
            if (!chars.empty()) {
                chars.pop_back();
            }
            chars.push_back('.');
        } else if (position >= 1 && position < input_str.length() && 
                   input_str.substr(position - 1, 2) == "at" && 
                   found_at && position != 1 && position != input_str.length() - 1) {
            if (!chars.empty()) {
                chars.pop_back();
            }
            chars.push_back('@');
            found_at = false;
        } else {
            chars.push_back(current_char);
        }
    }
    std::string result_str(chars.begin(), chars.end());
    std::cout << result_str << std::endl;
    return 0;
}
